        if (!value.startsWith("\"") && !value.startsWith("'")) {
            throw new IllegalArgumentException("Invalid attribute value: " + value);
        }
        try {
            java.util.Arrays.asList(value.split("\"|'|\"")).indexOf("\"");
            return true;
        } catch (Exception e) {
            return false;
        }
